logger = logging.getLogger(__name__)


class YouTubeThumbnailRepository:
    """Repository for managing cached YouTube thumbnails in DuckDB."""

    def __init__(self, conn: duckdb.DuckDBPyConnection | None = None):
        """Initialize repository.

        Args:
            conn: Optional DuckDB connection (uses thread-local if not provided)
        """
        self.conn = conn or get_connection()

    def save_thumbnail(
        self,
        video_id: str,
        original_url: str,
        cached_path: Path,
        title: str | None = None,
    ) -> YouTubeThumbnail:
        """Save thumbnail metadata to DuckDB.

        Args:
            video_id: YouTube video ID
            original_url: Original thumbnail URL
            cached_path: Local cached file path
            title: Optional video title

        Returns:
            Created YouTubeThumbnail instance

        Raises:
            duckdb.ConstraintException: If video_id already exists
        """
        logger.debug(f"{video_id=}, {cached_path=}")

        self.conn.execute(
            """
            INSERT INTO youtube_thumbnails (video_id, original_url, cached_path, title)
            VALUES (?, ?, ?, ?)
            """,
            [video_id, original_url, str(cached_path), title],
        )

        # Retrieve the created record
        result = self.conn.execute(
            "SELECT * FROM youtube_thumbnails WHERE video_id = ?", [video_id]
        ).fetchone()

        logger.info(f"Saved thumbnail metadata for {video_id=}")

        return YouTubeThumbnail(
            id=result[0],
            video_id=result[1],
            original_url=result[2],
            cached_path=Path(result[3]),
            title=result[4],
            downloaded_at=result[5],
        )

    def get_by_video_id(self, video_id: str) -> YouTubeThumbnail | None:
        """Retrieve thumbnail by YouTube video ID.

        Args:
            video_id: YouTube video ID

        Returns:
            YouTubeThumbnail if found, None otherwise
        """
        logger.debug(f"{video_id=}")

        result = self.conn.execute(
            "SELECT * FROM youtube_thumbnails WHERE video_id = ?", [video_id]
        ).fetchone()

        if not result:
            logger.debug(f"Thumbnail not found for {video_id=}")
            return None

        return YouTubeThumbnail(
            id=result[0],
            video_id=result[1],
            original_url=result[2],
            cached_path=Path(result[3]),
            title=result[4],
            downloaded_at=result[5],
        )

